import { Router } from 'express';
export function buatTodoRouter(todoService) {
  const r = Router();
  r.get('/', async (req, res) => res.json({ data: await todoService.daftar(req.pengguna.id) }));
  r.post('/', async (req, res) => {
    const t = await todoService.tambah(req.pengguna.id, req.body);
    res.status(201).location(`${req.baseUrl}/${t.id}`).json({ data: t });
  });
  r.get('/:id', async (req, res) => res.json({ data: await todoService.detail(req.pengguna.id, Number(req.params.id)) }));
  r.patch('/:id', async (req, res) => res.json({ data: await todoService.ubah(req.pengguna.id, Number(req.params.id), req.body) }));
  r.delete('/:id', async (req, res) => {
    await todoService.hapus(req.pengguna.id, Number(req.params.id));
    res.sendStatus(204);
  });
  return r;
}
// === src/app.js ===
import express from 'express';
import { AppError } from './errors.js';
import { buatTodoRouter } from './routes/todo.js';
export function buatApp({ todoService }) {
  const app = express();
  app.use(express.json());
  app.get('/health', (req, res) => res.json({ status: 'ok' }));
  app.use('/api/v1/todos', (req, res, next) => {
    req.pengguna = { id: Number(req.get('x-pengguna') ?? 1) }; // sementara, diganti JWT di materi 4
    next();
  }, buatTodoRouter(todoService));
  app.use((req, res) => res.status(404).json({ error: { kode: 'JALUR_TIDAK_ADA', pesan: 'Jalur tidak ditemukan' } }));
  app.use((err, req, res, next) => {
    if (!(err instanceof AppError)) err = new AppError(500, 'KESALAHAN_SERVER', 'Terjadi kesalahan di server');
    res.status(err.status).json({ error: { kode: err.kode, pesan: err.message } });
  });
  return app;
}
